        const card = t.firstElementChild;
        const w = card ? card.getBoundingClientRect().width + 16 : t.clientWidth;
        const p = Math.round(t.scrollLeft / w);
        const max = Math.max(1, t.scrollWidth - t.clientWidth);
        const frac = Math.min(1, Math.max(0, t.scrollLeft / max));
